def interleave_and_eval(operands, operators):
    if len(operands) != len(operators) + 1:
        raise ValueError("Operands must be one more than operators.")
    # Build expression by interleaving operands and operators
    parts = []
    for i, op in enumerate(operands):
        parts.append(str(op))
        if i < len(operators):
            parts.append(str(operators[i]))
    expr = " ".join(parts)
    # Evaluate safely by restricting builtins
    return eval(expr, {"__builtins__": None}, {})

