import sys, math

def round_half_away_from_zero(x):
    if isinstance(x, (int, float)):
        if x > 0:
            return int(math.floor(x + 0.5))
        elif x < 0:
            return int(math.ceil(x - 0.5))
        else:
            return 0
    else:
        try:
            return type(x)(round_half_away_from_zero(v) for v in x)
        except Exception:
            raise

