import re

def process_text(text):
    """
    Splits text by whitespace if present, else by comma, 
    else counts lowercase letters at odd positions in alphabet.
    """
    # Check for whitespace
    if re.search(r'\s', text):
        return text.split()
    # Check for comma
    elif ',' in text:
        return text.split(',')
    # Count lowercase letters at odd positions in alphabet
    else:
        # a=1 (odd), b=2 (even), c=3 (odd), etc.
        # We count letters where their position in alphabet is odd
        return sum(
            1 for char in text 
            if char.islower() and ((ord(char) - ord('a') + 1) % 2 == 1)
        )

