def count_even_odd_digits(n):
    n = abs(n)
    even = 0
    odd = 0
    if n == 0:
        return 1, 0  # 0 is considered even
    while n:
        digit = n % 10
        if digit % 2 == 0:
            even += 1
        else:
            odd += 1
        n //= 10
    return even, odd

