def second_smallest(iterable):
    it = iter(iterable)
    try:
        first = next(it)
        second = None
        for x in it:
            if x < first:
                second, first = first, x
            elif second is None or x < second and x != first:
                second = x
        if second is None:
            raise ValueError("There is no second smallest value")
        return second
    except StopIteration:
        raise ValueError("Iterable must contain at least two elements")

